parameters.jsCode:
const body = $input.first().json.body;
const required = ['prospect_company', 'call_notes', 'rep_name'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.call_notes.trim().length < 50) return [{ json: { valid: false, error: 'call_notes too short' } }];
const stages = ['discovery', 'demo', 'technical_evaluation', 'proposal', 'negotiation', 'closing', 'renewal'];
const stage = stages.includes(body.deal_stage) ? body.deal_stage : 'discovery';
return [{ json: {
  valid: true,
  prospectCompany: body.prospect_company.trim(),
  prospectContact: body.prospect_contact || '',
  prospectTitle: body.prospect_title || '',
  repName: body.rep_name.trim(),
  repEmail: body.rep_email || '',
  dealStage: stage,
  callNotes: body.call_notes.trim().slice(0, 5000),
  dealValue: parseFloat(body.deal_value) || null,
  currency: body.currency || 'USD',
  productOffered: body.product_offered || '',
  competitorsInvolved: Array.isArray(body.competitors_involved) ? body.competitors_involved : (body.competitors_involved||'').split(',').map(c=>c.trim()).filter(Boolean),
  callDate: body.call_date || new Date().toISOString().split('T')[0],
  managerEmail: body.manager_email || '',
  replyEmail: body.reply_email || null
} }];

values.content:
Debrief this sales call.

Prospect: {{ $json.prospectContact || 'unknown contact' }} at {{ $json.prospectCompany }}{{ $json.prospectTitle ? ' (' + $json.prospectTitle + ')' : '' }}
Rep: {{ $json.repName }}
Stage: {{ $json.dealStage.replace(/_/g,' ') }}
Date: {{ $json.callDate }}
Deal value: {{ $json.dealValue ? $json.currency + $json.dealValue : 'unknown' }}
Product: {{ $json.productOffered || 'not specified' }}
Competitors: {{ $json.competitorsInvolved.join(', ') || 'none mentioned' }}

Call notes:
{{ $json.callNotes }}

Return this JSON:
{
  "deal_summary": "2-3 sentences: where this deal stands and the most important thing to know about it",
  "buying_signals": ["specific things the prospect said or did that indicate genuine interest or purchase intent"],
  "objections_raised": [
    {"objection": "what they said", "type": "price | timing | technical | authority | competition | need", "rebuttal_suggested": "how to address this"}
  ],
  "pain_points_uncovered": ["specific pains the prospect expressed — use their language if captured"],
  "decision_process": {
    "decision_maker": "who actually signs — or unknown",
    "other_stakeholders": ["others involved in the decision"],
    "timeline": "their stated or implied buying timeline",
    "evaluation_criteria": ["what they care most about"]
  },
  "competitive_situation": {
    "competitors_active": ["who else they're evaluating"],
    "our_position": "where we stand relative to alternatives based on what was said"
  },
  "deal_health": {
    "score": 7,
    "rationale": "why this score (1-10)",
    "biggest_risk": "the single thing most likely to lose this deal"
  },
  "next_steps": [
    {"action": "specific next action", "owner": "rep | prospect | manager | se", "due": "specific timeframe", "critical": true}
  ],
  "coaching_note": "one specific coaching observation for this rep — what they did well or a skill gap surfaced in these notes"
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let debrief;
try { debrief = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
debrief._meta = { prospectCompany: input.prospectCompany, prospectContact: input.prospectContact, repName: input.repName, repEmail: input.repEmail, dealStage: input.dealStage, dealValue: input.dealValue, currency: input.currency, callDate: input.callDate, managerEmail: input.managerEmail, replyEmail: input.replyEmail };
return [{ json: debrief }];

const d = $input.first().json;
const m = d._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const score = d.deal_health?.score || 5;
const scoreColor = score >= 7 ? '#16a34a' : score >= 5 ? '#d97706' : '#dc2626';
const stageColors = {discovery:'#6b7280',demo:'#2563eb',technical_evaluation:'#7c3aed',proposal:'#0891b2',negotiation:'#d97706',closing:'#16a34a',renewal:'#2563eb'};
const sc = stageColors[m.dealStage]||'#6b7280';
const signalList = (d.buying_signals||[]).map(s => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f0fdf4;color:#166534">✓ ${esc(s)}</div>`).join('');
const objectionCards = (d.objections_raised||[]).map(o => `<div style="border:1px solid #fde68a;border-radius:6px;margin-bottom:8px;overflow:hidden"><div style="background:#fffbeb;padding:8px 12px;font-size:13px;font-weight:600;color:#92400e">${esc(o.objection)} <span style="font-weight:400;color:#b45309">[${esc(o.type)}]</span></div><div style="padding:8px 12px;font-size:13px;color:#374151">${esc(o.rebuttal_suggested)}</div></div>`).join('');
const painPoints = (d.pain_points_uncovered||[]).map(p => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f0f9ff;color:#1e40af">→ ${esc(p)}</div>`).join('');
const dp = d.decision_process||{};
const nextSteps = (d.next_steps||[]).map(ns => `<tr style="border-bottom:1px solid #f3f4f6${ns.critical?' background:#fffbeb':''}"><td style="padding:8px 12px;font-size:13px">${ns.critical?'⚡ ':''  }${esc(ns.action)}</td><td style="padding:8px 12px;font-size:12px;color:#6b7280">${esc(ns.owner)}</td><td style="padding:8px 12px;font-size:12px;color:#6b7280">${esc(ns.due)}</td></tr>`).join('');
const evalCriteria = (dp.evaluation_criteria||[]).map(e => `<span style="display:inline-block;background:#f3f4f6;color:#374151;font-size:12px;padding:3px 10px;border-radius:12px;margin:3px 3px 0 0">${esc(e)}</span>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:700px;margin:0 auto">
  <div style="background:#1e293b;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0">
    <div style="display:flex;gap:8px;align-items:center;margin-bottom:5px">
      <span style="background:${sc};color:#fff;font-size:11px;font-weight:700;padding:2px 10px;border-radius:8px">${esc(m.dealStage.replace(/_/g,' ').toUpperCase())}</span>
      <span style="font-size:12px;color:#64748b">${esc(m.callDate)}</span>
      ${m.dealValue?`<span style="font-size:12px;color:#64748b">· ${m.currency}${m.dealValue.toLocaleString()}</span>`:''}
    </div>
    <div style="font-size:19px;font-weight:700">${esc(m.prospectCompany)}</div>
    <div style="font-size:13px;color:#94a3b8;margin-top:3px">${m.prospectContact?esc(m.prospectContact)+' · ':''  }Rep: ${esc(m.repName)}</div>
  </div>
  <div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:none;display:flex;align-items:flex-start;gap:16px">
    <div style="text-align:center;flex-shrink:0"><div style="font-size:32px;font-weight:800;color:${scoreColor}">${score}</div><div style="font-size:11px;color:#9ca3af">/ 10</div></div>
    <div><p style="font-size:14px;line-height:1.7;color:#374151;margin:0 0 6px">${esc(d.deal_summary)}</p><div style="font-size:13px;color:#dc2626">⚠ ${esc(d.deal_health?.biggest_risk)}</div></div>
  </div>
  ${signalList?`<div style="background:#f0fdf4;padding:14px 26px;border:1px solid #bbf7d0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:7px">Buying signals</div>${signalList}</div>`:''}
  ${objectionCards?`<div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:8px">Objections raised</div>${objectionCards}</div>`:''}
  ${painPoints?`<div style="background:#eff6ff;padding:14px 26px;border:1px solid #bfdbfe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:7px">Pain points</div>${painPoints}</div>`:''}
  <div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Decision process</div>
    <div style="font-size:13px;margin-bottom:4px"><strong>Decision maker:</strong> ${esc(dp.decision_maker||'unknown')}</div>
    <div style="font-size:13px;margin-bottom:4px"><strong>Timeline:</strong> ${esc(dp.timeline||'not discussed')}</div>
    ${evalCriteria?`<div style="margin-top:6px">${evalCriteria}</div>`:''}
  </div>
  ${nextSteps?`<div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Next steps</div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="font-size:11px;text-transform:uppercase;color:#9ca3af"><th style="padding:6px 12px;text-align:left">Action</th><th style="padding:6px 12px;text-align:left">Owner</th><th style="padding:6px 12px;text-align:left">Due</th></tr></thead>
      <tbody>${nextSteps}</tbody>
    </table>
  </div>`:''}
  ${d.coaching_note?`<div style="background:#fafafa;padding:12px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px">Coaching note (for manager)</div><div style="font-size:13px;color:#6b7280;font-style:italic">${esc(d.coaching_note)}</div></div>`:''}
  <div style="background:#1e293b;color:#475569;font-size:11px;padding:10px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Sales Debrief · ${esc(m.prospectCompany)} · ${esc(m.callDate)}</div>
</div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, managerEmail: m.managerEmail, repEmail: m.repEmail, prospectCompany: m.prospectCompany, dealHealth: d.deal_health?.score, debrief: d } }];
